class Solution {
public:
    int maxSubArray(std::vector<int>& nums) {
        int best = nums[0];
        int endingHere = nums[0];
        for (std::size_t index = 1; index < nums.size(); ++index) {
            endingHere = std::max(nums[index], endingHere + nums[index]);
            best = std::max(best, endingHere);
        }
        return best;
    }
};

